40	  // Scrolling on the open book before the page moves on: the pages settle and the aayat can be read. It was 1.4
41	  // screens (0.4 to settle, 1 for the aayat) until the user found it too long; TRYOUT "Scroll once it opens".
42	  let hold = 0.35;
43	  let total = REST + OPEN + hold; // .hero in styles.css is one screen taller than this, through --timeline
44	  const NAME_GONE = 8; // the headline has faded out by this frame, early in the opening
45	
46	  // Smoothing ---------------------------------------------------------------------
47	
48	  // A mouse wheel scrolls in steps, so everything glides toward the scroll position instead of
49	  // jumping to it, and the book cross-fades between frames. The user chose this "slow glide" by eye.
50	  let glide = 0.28; // roughly the seconds it takes to close two thirds of the gap; 0 jumps straight there
51	  let blend = true; // cross-fade neighbouring frames, rather than showing whole frames only
52	  // Stopped between two frames, the cross-fade settles onto the nearer frame over this many seconds: held still, it looks blurred.
53	  const SHARPEN = 0.25;
54	  // Once scrolling reaches this, the aayat fade in by themselves (the transition on .group), not with the scroll.
55	  const APPEAR = REST + OPEN * 0.9;
56	
57	  // A book left half open opens or closes by itself once scrolling stops: toward the nearer end, or the way the
58	  // visitor was scrolling. 'off' leaves it where it stopped.
59	  let finish = 'direction';
60	  let finishSpeed = 1;     // screens of scrolling a second; a half-open book is about one screen from either end
61	  const FINISH_WAIT = 180; // ms without scrolling before it finishes
62	  // The same goes for the ending: the page never rests with it part way in (settleEnding). TRYOUT "Ending locks into place".
63	  let lockEnding = true;
64	
65	  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)');
66	  const wide = matchMedia('(min-width: 768px)'); // "Under the book" is for computers only
67	  const hero = document.querySelector('.hero');
68	  const stage = hero.querySelector('.stage');
69	  const subject = stage.querySelector('.subject'); // the book and its aayat, moved together by atmosphere.js
70	  const canvas = subject.querySelector('canvas');
71	  const wordmark = stage.querySelector('.wordmark');
72	  const ctx = canvas.getContext('2d');
73	  const close = document.querySelector('.close'); // the ending, after the book
74	  const closeInner = close.querySelector('.inner');
75	  const topbar = document.querySelector('.topbar');
76	  const resting = stage.querySelectorAll('.wordmark, .beside'); // shown with the closed book; they fade as it opens
77	  const themeButton = topbar.querySelector('.theme');
78	  const themeColor = document.querySelector('meta[name="theme-color"]');
79	
80	  const frames = []; // decoded images by index, filled in as they arrive
81	  const rights = []; // measured right edge of the book in each frame
82	  const started = new Set();
83	  const groups = []; // one element per group of aayat, filled in when aayat.json arrives
84	
85	  let scale = 1;      // footage pixels to CSS pixels, set on resize
86	  let pos = null;     // scroll position shown, in screens; lags the real one while gliding
87	  let painted = null; // position last shown
88	  let drawn = null;   // frame last drawn; fractional between frames
89	  let last = 0;       // time of the previous glide step, 0 when at rest
90	  let dirty = true;
91	  let queued = false;
92	  let visible = true;
93	  let showing = false; // whether the pages show aayat
94	  let current = -1;   // the group of aayat last picked
95	  let previous = -1;  // the last group shown, so the next pass shows a different one
96	  let moving = false; // still gliding toward the scroll position; atmosphere.js keeps the book still meanwhile
97	  let sharpen = 1;    // 0 while moving, 1 once settled onto a whole frame
98	  let direction = 0;  // 1 when the visitor last scrolled down, -1 up
99	  let lastY = scrollY;
100	  let touching = false;
101	  let finishTimer = 0;
102	  let autoScroll = 0; // the animation frame of a scroll the page started itself, 0 when none
103	  let ended = false;  // scrolling has reached the end of the book's screens
104	
105	  // Loading -----------------------------------------------------------------------
106	
107	  function load(i) {
108	    if (started.has(i)) return;
109	    started.add(i);
110	    const img = new Image();
111	    img.src = urls[i];
112	    img.decode().then(
113	      () => {
114	        frames[i] = img;
115	        rights[i] = measureRight(img);
116	        if (i >= LAST - 3) place(); // the open book's measured edge sets where the pages are
117	        dirty = true;
118	        schedule();
119	      },
120	      () => console.warn(`Frame missing: ${urls[i]}`), // the nearest loaded frame is drawn instead
121	    );
122	  }
123	
124	  // First and last frames, then coarse to fine, so scrubbing works before everything arrives.
125	  function loadAll() {
126	    load(0);
127	    load(LAST);
128	    for (const step of [8, 4, 2, 1]) {
129	      for (let i = 0; i <= LAST; i += step) load(i);
130	    }
131	  }
132	
133	  // The ivory Qur'an for light mode, fetched only when the page first turns light.
134	  const ivory = new Image();
135	  let ivoryReady = false;
136	
137	  function loadIvory() {
138	    if (ivory.getAttribute('src')) return;
139	    ivory.src = IVORY.src;
140	    ivory.decode().then(
141	      () => {
142	        ivoryReady = true;
143	        dirty = true;
144	        schedule();
145	      },
146	      () => console.warn(`Missing: ${IVORY.src}`),
147	    );
148	  }
149	
150	  // Once the cover passes upright its cream lining faces the camera, so the book's right
151	  // edge is the rightmost bright pixel along the middle row, and never less than the spine.
152	  const probe = document.createElement('canvas');
153	  probe.width = SRC_W;
154	  probe.height = 1;
155	  const probeCtx = probe.getContext('2d', { willReadFrequently: true });
156	
157	  function measureRight(img) {
158	    try {
159	      probeCtx.drawImage(img, 0, SRC_H / 2, SRC_W, 1, 0, 0, SRC_W, 1);
160	      const px = probeCtx.getImageData(0, 0, SRC_W, 1).data;
161	      for (let x = SRC_W - 1; x > SPINE; x--) {
162	        if (px[x * 4] + px[x * 4 + 1] + px[x * 4 + 2] > 300) return x + 1;
163	      }
164	      return SPINE;
165	    } catch {
166	      return null; // pixels unreadable, e.g. opened as a file rather than through serve.js
167	    }
168	  }
169

